// Tests of the first-order Ambisonics decoder: sad_decoder(), the SAD matrix with max-rE
// weights for a loudspeaker layout, and decode_bformat(), which decodes B-format signals
// to the loudspeakers. Results are compared with MATLAB values (getMaxREweights,
// ambiDecoder), the reference data generated by Iceberg MATLAB v1.0.0 and closed forms.

#include "io/wav_loader.h"
#include "rendering/ambisonics_decoder.h"
#include "iceberg_signal.h"
#include "test_helpers.h"

#include <gtest/gtest.h>

#include <Eigen/Dense>

#include <array>
#include <cmath>
#include <cstdio>
#include <string>

namespace {

constexpr double kPi = 3.14159265358979323846;

using iceberg::test::record_measure;

// MATLAB getMaxREweights(1) at 20-digit precision, captured via:
//   matlab -batch "addpath(...); a_n = getMaxREweights(1); fprintf('%.20f\n', a_n);"
constexpr double kMaxREweightsOrder1[4] = {
    1.00000000000000000000,
    0.57443052062777699707,
    0.57443052062777699707,
    0.57443052062777699707,
};

// Captured from MATLAB ambiDecoder([180 0; 270 0; 0 0; 90 0], 'SAD', 1, 1).
// ACN order [W, Y, Z, X]; column Z exactly
// zero for the 2D ring layout (elev=0 everywhere).
const std::array<std::array<double, 4>, 4> kSadDecoder4Cardinal = {{
    {0.88622692545275794,  1.0798263638876786e-16, 0.0, -0.88174514042701591},
    {0.88622692545275794, -0.88174514042701591,    0.0, -1.6197395458315177e-16},
    {0.88622692545275794,  0.0,                    0.0,  0.88174514042701591},
    {0.88622692545275794,  0.88174514042701591,    0.0,  5.3991318194383928e-17},
}};

Eigen::MatrixXd four_cardinal_ls_dir() {
    Eigen::MatrixXd m(4, 2);
    m << 180, 0,
         270, 0,
           0, 0,
          90, 0;
    return m;
}

Eigen::MatrixXd uniform_ring_ls_dir(int n) {
    Eigen::MatrixXd m(n, 2);
    for (int i = 0; i < n; ++i) {
        m(i, 0) = 360.0 * static_cast<double>(i) / static_cast<double>(n);
        m(i, 1) = 0.0;
    }
    return m;
}

// === 1. Shape: 4-cardinal layout ========================================

// The SAD decoder for 4 loudspeakers at 180, 270, 0 and 90 deg is a 4 x 4 matrix: one
// row per loudspeaker, one column per first-order component.
TEST(SadDecoder, ShapeFourCardinal) {
    const auto D = iceberg::rendering::sad_decoder(four_cardinal_ls_dir());
    EXPECT_EQ(D.rows(), 4);
    EXPECT_EQ(D.cols(), 4);
}

// === 2. Shape: arbitrary uniform ring ===================================

// For a uniform ring of 8 loudspeakers the decoder is 8 x 4, and its Z column is exactly
// zero, since every loudspeaker has elevation 0.
TEST(SadDecoder, ShapeUniformEightLs) {
    const auto D = iceberg::rendering::sad_decoder(uniform_ring_ls_dir(8));
    EXPECT_EQ(D.rows(), 8);
    EXPECT_EQ(D.cols(), 4);
    // Z column must be all zero for any 2D ring (elev=0 everywhere).
    EXPECT_EQ(D.col(2).cwiseAbs().maxCoeff(), 0.0);
}

// === 3. Plane wave at 0° → energy at LS-0° ===============================

// One B-format sample of a plane wave from 0 deg (FuMa: W = 1/sqrt(2), X = 1, Y = Z = 0),
// decoded to the 4-cardinal layout, has its largest amplitude on the loudspeaker at
// 0 deg and a smaller one on the opposite loudspeaker at 180 deg.
TEST(SadDecoder, PlaneWaveAtZeroDegrees) {
    // Plane wave from azi=0°, elev=0° as a B-Format impulse.
    // FuMa: W = 1/√2, X = cos(0)cos(0) = 1, Y = sin(0)cos(0) = 0, Z = sin(0) = 0.
    iceberg::Signal bf;
    bf.samples = Eigen::MatrixXf(1, 4);
    bf.samples << static_cast<float>(1.0 / std::sqrt(2.0)), 1.0f, 0.0f, 0.0f;
    bf.sample_rate = 44100.0;

    const auto D = iceberg::rendering::sad_decoder(four_cardinal_ls_dir());
    const auto ls_sig = iceberg::rendering::decode_bformat(bf, D);

    // ls_dir order: [180°, 270°, 0°, 90°]. Channel 2 (LS-0°) should
    // dominate.
    Eigen::Index dom;
    ls_sig.samples.row(0).cwiseAbs().maxCoeff(&dom);
    EXPECT_EQ(dom, 2);
    // Diametrically opposite LS (180°) must be the minimum (or near-zero).
    EXPECT_LT(std::abs(ls_sig.samples(0, 0)),
              std::abs(ls_sig.samples(0, 2)));
}

// === 4. Plane wave at 90° → energy at LS-90° =============================

// One B-format sample of a plane wave from 90 deg (FuMa: W = 1/sqrt(2), Y = 1, X = Z = 0),
// decoded to the 4-cardinal layout, has its largest amplitude on the loudspeaker at 90 deg.
TEST(SadDecoder, PlaneWaveAtNinetyDegrees) {
    iceberg::Signal bf;
    bf.samples = Eigen::MatrixXf(1, 4);
    // azi=90°: X = cos(90°) = 0, Y = sin(90°) = 1, Z = 0.
    bf.samples << static_cast<float>(1.0 / std::sqrt(2.0)), 0.0f, 1.0f, 0.0f;
    bf.sample_rate = 44100.0;

    const auto D = iceberg::rendering::sad_decoder(four_cardinal_ls_dir());
    const auto ls_sig = iceberg::rendering::decode_bformat(bf, D);

    Eigen::Index dom;
    ls_sig.samples.row(0).cwiseAbs().maxCoeff(&dom);
    EXPECT_EQ(dom, 3);  // ls_dir[3] = 90°
}

// === 5. Energy property: column-W is constant on uniform rings ==========

// On uniform rings of 4, 6, 8, 12, 16 and 24 loudspeakers, all entries of the W column
// of the SAD decoder are equal (the order-0 spherical harmonic is the same in every
// direction), within 1e-15, the rounding of 64-bit floats.
TEST(SadDecoder, WColumnConstantOnUniformRing) {
    // For SAD on a uniform ring, Y_ls[0, ls] = 1/√(4π) for every LS,
    // so the W column of D is the constant `(4π/n_ls) · 1/√(4π) · 1`
    // = √(4π) / n_ls · ... let's compute directly: π / (n_ls / 2) ·
    // (1/√(4π)) ... Actually the constant value is just (4π/n) ·
    // 1/√(4π) = √(4π)/n = √(π)/(n/2). Either way, all entries equal.
    double worst = 0.0;
    for (const int n : {4, 6, 8, 12, 16, 24}) {
        const auto D = iceberg::rendering::sad_decoder(uniform_ring_ls_dir(n));
        const double w0 = D(0, 0);
        for (int i = 1; i < n; ++i) {
            EXPECT_NEAR(D(i, 0), w0, 1e-15) << "n=" << n << " i=" << i;
            worst = std::max(worst, std::abs(D(i, 0) - w0));
        }
    }
    record_measure("W column spread, worst ring", worst, 1e-15, "abs");
}

// === 6. max-rE weights cross-check vs MATLAB @ 1e-15 ====================

// The max-rE weights are recovered from the decoder of one loudspeaker at (0, 0): a_0 as
// the W entry over sqrt(4 pi) and a_1 as the X entry over sqrt(12 pi). Both are compared
// with MATLAB getMaxREweights(1) within 1e-15, the rounding of 64-bit floats.
TEST(SadDecoder, MaxREWeightsMatchMatlab) {
    // The decoder factors max-rE in via diag(a_n). On a 1-LS layout
    // with that LS at azi=0,elev=0, Y_ls = [1/√(4π); 0; 0; √(3/(4π))],
    // and D = (4π/1) · Y_ls.' · diag(a_n) yields rows whose values
    // are direct multiples of a_n. Easiest indirect way to validate
    // a_n at 1e-15: run on a "nice" layout and back out a_n[i] = D[i] /
    // expected_unweighted_value.
    //
    // But we'd rather test a_n directly. Reach in via the closed-form
    // equivalence: the W column of the SAD decoder on a uniform N-LS
    // ring, scaled by √(4π) / (4π/N) = N/√(4π), equals a_n[0]:
    //   D[i, 0] = (4π/N) · (1/√(4π)) · a_n[0] = √(4π)/N · a_n[0]
    //   ⇒ a_n[0] = D[i, 0] · N / √(4π)
    //
    // Same trick for the Y/X columns scales by the magnitude of the
    // m=±1 SH on the ring. For the constant a_n[1..3] check, simpler:
    // place a single LS at (0, 0), where the X column collapses to
    // (4π/1) · √(3/(4π)) · a_n[3] = √(3·4π) · a_n[3].
    Eigen::MatrixXd one_ls(1, 2);
    one_ls << 0, 0;
    const auto D = iceberg::rendering::sad_decoder(one_ls);
    // D is (1 × 4). D[0, 0] = (4π) · (1/√(4π)) · a_n[0] = √(4π) · a_n[0].
    const double a0 = D(0, 0) / std::sqrt(4.0 * kPi);
    record_measure("a_n[0]", std::abs(a0 - kMaxREweightsOrder1[0]), 1e-15, "abs");
    EXPECT_NEAR(a0, kMaxREweightsOrder1[0], 1e-15);
    // D[0, 3] = (4π) · √(3/(4π)) · a_n[3] = √(12π) · a_n[3].
    const double a3 = D(0, 3) / std::sqrt(12.0 * kPi);
    record_measure("a_n[3]", std::abs(a3 - kMaxREweightsOrder1[3]), 1e-15, "abs");
    EXPECT_NEAR(a3, kMaxREweightsOrder1[3], 1e-15);
}

// === 7. Decoder matrix exact match vs MATLAB ambiDecoder @ 1e-12 ========

// The SAD decoder for the 4-cardinal layout (180, 270, 0, 90 deg) is compared entry by
// entry with the matrix of MATLAB ambiDecoder(ls_dir, 'SAD', 1, 1), within 1e-12, a
// margin for trigonometric rounding on entries of order 1.
TEST(SadDecoder, MatrixMatchesMatlabFourCardinal) {
    const auto D = iceberg::rendering::sad_decoder(four_cardinal_ls_dir());
    ASSERT_EQ(D.rows(), 4);
    ASSERT_EQ(D.cols(), 4);
    double worst = 0.0;
    for (int r = 0; r < 4; ++r) {
        for (int c = 0; c < 4; ++c) {
            EXPECT_NEAR(D(r, c), kSadDecoder4Cardinal[r][c], 1e-12)
                << "r=" << r << " c=" << c;
            worst = std::max(worst, std::abs(D(r, c) - kSadDecoder4Cardinal[r][c]));
        }
    }
    record_measure("decoder matrix, worst entry", worst, 1e-12, "abs");
}

// === Defensive guards ====================================================

// Invalid inputs are rejected with std::invalid_argument: for sad_decoder(), a direction
// matrix with one column or with no rows; for decode_bformat(), a 3-channel B-format
// signal or a decoder with 3 columns.
TEST(SadDecoder, ThrowsOnInvalidInputs) {
    // sad_decoder: ls_dirs with < 2 cols.
    Eigen::MatrixXd one_col(4, 1);
    one_col << 0, 90, 180, 270;
    EXPECT_THROW(iceberg::rendering::sad_decoder(one_col),
                 std::invalid_argument);

    // sad_decoder: empty rows.
    Eigen::MatrixXd empty(0, 2);
    EXPECT_THROW(iceberg::rendering::sad_decoder(empty),
                 std::invalid_argument);

    // decode_bformat: B-Format with wrong channel count.
    iceberg::Signal three_ch;
    three_ch.samples = Eigen::MatrixXf::Zero(100, 3);
    three_ch.sample_rate = 44100.0;
    const auto D = iceberg::rendering::sad_decoder(four_cardinal_ls_dir());
    EXPECT_THROW(iceberg::rendering::decode_bformat(three_ch, D),
                 std::invalid_argument);

    // decode_bformat: decoder with wrong column count.
    iceberg::Signal four_ch;
    four_ch.samples = Eigen::MatrixXf::Zero(100, 4);
    four_ch.sample_rate = 44100.0;
    Eigen::MatrixXd bad_decoder(4, 3);
    EXPECT_THROW(iceberg::rendering::decode_bformat(four_ch, bad_decoder),
                 std::invalid_argument);
}

// Why this test exists: every fixture in this repo uses a 2D ring
// (ls_dir(:, 1) = 0 for all LSes), so the Z column of every fixture-
// derived decoder is identically zero. A future refactor that
// "simplifies" the decoder to a 2D-only formulation — e.g. dropping
// the Y_10 row from `compute_rsh_order1`, or hardcoding Z=0 — would
// pass every other test in this file. This test feeds a non-zero
// elevation, asserts the Z column is non-zero, and pins the polarch
// formula by checking a closed-form value at a single LS.

// The decoder of one loudspeaker at azimuth 0 and elevation 45 deg is compared with its
// closed form within 1e-12: W = sqrt(4 pi), Y = 0, Z = X = sqrt(12 pi) (sqrt(2)/2) a_1,
// with a_1 the max-rE weight. The Z entry must also exceed 0.5, so that the elevation
// term, which every ring layout leaves at zero, is exercised.
TEST(SadDecoder, NonRingLayoutWithElevation) {
    // Single LS at (azi = 0°, elev = 45°). Closed-form decoder:
    //   D[0, 0] (W) = (4π / 1) · 1/√(4π) · a_n[0] = √(4π) · 1
    //   D[0, 1] (Y) = (4π / 1) · √(3/(4π)) · cos(45°) · sin(0°) · a_n[1]
    //               = 0
    //   D[0, 2] (Z) = (4π / 1) · √(3/(4π)) · sin(45°) · a_n[2]
    //               = √(12π) · (√2 / 2) · a_n[2]
    //   D[0, 3] (X) = (4π / 1) · √(3/(4π)) · cos(45°) · cos(0°) · a_n[3]
    //               = √(12π) · (√2 / 2) · a_n[3]
    Eigen::MatrixXd one_ls(1, 2);
    one_ls << 0, 45;

    const auto D = iceberg::rendering::sad_decoder(one_ls);
    ASSERT_EQ(D.rows(), 1);
    ASSERT_EQ(D.cols(), 4);

    const double sqrt12pi = std::sqrt(12.0 * kPi);
    const double half_sqrt2 = std::sqrt(2.0) / 2.0;
    const double a_n_lobe = kMaxREweightsOrder1[1];  // shared across m

    EXPECT_NEAR(D(0, 0), std::sqrt(4.0 * kPi), 1e-12);
    EXPECT_NEAR(D(0, 1), 0.0, 1e-12);  // sin(0°) = 0
    EXPECT_NEAR(D(0, 2), sqrt12pi * half_sqrt2 * a_n_lobe, 1e-12);
    EXPECT_NEAR(D(0, 3), sqrt12pi * half_sqrt2 * a_n_lobe, 1e-12);
    const double worst = std::max(
        {std::abs(D(0, 0) - std::sqrt(4.0 * kPi)), std::abs(D(0, 1)),
         std::abs(D(0, 2) - sqrt12pi * half_sqrt2 * a_n_lobe),
         std::abs(D(0, 3) - sqrt12pi * half_sqrt2 * a_n_lobe)});
    record_measure("closed form, worst entry", worst, 1e-12, "abs");

    // The key regression guard: Z column is materially non-zero.
    EXPECT_GT(std::abs(D(0, 2)), 0.5);
}

// === 8. Against MATLAB: stages/rt_05, decoder matrix and decoded late field ===

// Against the rt_05 stage files of Iceberg MATLAB v1.0.0: the decoder for the default
// layout matches MATLAB's matrix within 1e-14 per entry, and the convolved B-format at 30,
// 100 and 225 deg, once decoded, matches MATLAB's decoded late field within 1e-9 RMS per
// channel, the 32-bit float rounding of the reference files.
TEST(DecodeBformat, StagesMatchMatlab) {
    ICEBERG_SKIP_IF_NO_FIXTURES();
    const auto ls_dir = iceberg::test::load_case_setup(std::string("sweep/rt_05")).ls_dir;
    const auto D = iceberg::rendering::sad_decoder(ls_dir);

    // MATLAB's D4 (ambiDecoder 'SAD' order 1, max-rE), as written by jsonencode.
    const auto ref = iceberg::test::load_fixture_json("stages/rt_05/stages.json").at("decoder");
    ASSERT_EQ(static_cast<Eigen::Index>(ref.size()), D.rows());
    double worst_entry = 0.0;
    for (Eigen::Index i = 0; i < D.rows(); ++i) {
        ASSERT_EQ(static_cast<Eigen::Index>(ref[i].size()), D.cols());
        for (Eigen::Index j = 0; j < D.cols(); ++j) {
            EXPECT_NEAR(D(i, j), ref[i][j].get<double>(), 1e-14) << i << "," << j;
            worst_entry = std::max(worst_entry, std::abs(D(i, j) - ref[i][j].get<double>()));
        }
    }
    record_measure("stages/rt_05 decoder matrix, worst entry", worst_entry, 1e-14, "abs");

    double worst_rms = 0.0;
    for (const int angle : {30, 100, 225}) {
        char in_name[48], out_name[48];
        std::snprintf(in_name, sizeof(in_name), "stages/rt_05/amb_convolved_az_%03d.wav", angle);
        std::snprintf(out_name, sizeof(out_name), "stages/rt_05/amb_decoded_az_%03d.wav", angle);
        const auto bf = iceberg::io::load_wav(iceberg::test::fixture_file(in_name));
        const auto expected = iceberg::io::load_wav(iceberg::test::fixture_file(out_name));
        const auto out = iceberg::rendering::decode_bformat(bf, D);
        ASSERT_EQ(out.samples.rows(), expected.samples.rows());
        ASSERT_EQ(out.samples.cols(), expected.samples.cols());
        const auto d = iceberg::test::diff_stats(out.samples, expected.samples);
        EXPECT_LT(d.worst_rms, 1e-9) << angle;
        worst_rms = std::max(worst_rms, d.worst_rms);
    }
    record_measure("stages/rt_05 decoded, worst RMS (az 30, 100, 225)", worst_rms, 1e-9, "rms");
}

}  // namespace
